            /// <summary>
            ///   Ergonomic wrapper over <c>SDL_GetGamepadBindings</c>.
            /// </summary>
            /// <param name="gamepad">a gamepad.</param>
            /// <exception cref="SdlException">The SDL call failed; the message carries the
            ///   <c>SDL_GetError</c> text.</exception>
            /// <remarks>
            ///   SDL returns a freshly <c>SDL_malloc</c>'d buffer for this call; the returned array is a managed copy,
            ///   and the native buffer is freed with <c>SDL_free</c> before this method returns.
            /// </remarks>
            public static SdlGamepadBinding[] GetGamepadBindings(SdlGamepad gamepad)
            {
                int count;
                var ptr = PInvoke.GetGamepadBindings(gamepad, &count);
                if (ptr is null)
                    throw SdlException.FromError("SDL_GetGamepadBindings failed");
                try
                {
                    var result = new SdlGamepadBinding[count];
                    for (var i = 0; i < count; i++)
                        result[i] = *(SdlGamepadBinding*)ptr[i];
                    return result;
                }
                finally
                {
                    PInvoke.Free(ptr);
                }
            }

