            /// <returns>the SDL_GamepadButtonLabel enum corresponding to the button label.</returns>
            /// <threadsafety>
            ///   It is safe to call this function from any thread.
            /// </threadsafety>
            /// <since>
            ///   This function is available since SDL 3.2.0.
            /// </since>
            /// <seealso cref="Brutal.SdlApi.Sdl.PInvoke.GetGamepadButtonLabelForType"/>
            public static SdlGamepadButtonLabel GetGamepadButtonLabel(SdlGamepad gamepad, SdlGamepadButton button) =>
                PInvoke.GetGamepadButtonLabel(gamepad, button);

            /// <summary>
            ///   Get the number of touchpads on a gamepad.
            /// </summary>
            /// <param name="gamepad">a gamepad.</param>
            /// <returns>number of touchpads.</returns>
            /// <threadsafety>
            ///   It is safe to call this function from any thread.
            /// </threadsafety>
            /// <since>
            ///   This function is available since SDL 3.2.0.
            /// </since>
            /// <seealso cref="Brutal.SdlApi.Sdl.PInvoke.GetNumGamepadTouchpadFingers"/>
            public static int GetNumGamepadTouchpads(SdlGamepad gamepad) => PInvoke.GetNumGamepadTouchpads(gamepad);

            /// <summary>
            ///   Get the number of supported simultaneous fingers on a touchpad on a game
            ///   gamepad.
            /// </summary>
            /// <param name="gamepad">a gamepad.</param>
            /// <param name="touchpad">a touchpad.</param>
            /// <returns>number of supported simultaneous fingers.</returns>
            /// <threadsafety>
            ///   It is safe to call this function from any thread.
            /// </threadsafety>
            /// <since>
            ///   This function is available since SDL 3.2.0.
            /// </since>
            /// <seealso cref="Brutal.SdlApi.Sdl.PInvoke.GetGamepadTouchpadFinger"/>
            /// <seealso cref="Brutal.SdlApi.Sdl.PInvoke.GetNumGamepadTouchpads"/>
            public static int GetNumGamepadTouchpadFingers(SdlGamepad gamepad, int touchpad) =>
                PInvoke.GetNumGamepadTouchpadFingers(gamepad, touchpad);

            /// <summary>
            ///   Return whether a gamepad has a particular sensor.
            /// </summary>
            /// <param name="gamepad">the gamepad to query.</param>
            /// <param name="type">the type of sensor to query.</param>
            /// <returns>true if the sensor exists, false otherwise.</returns>
            /// <threadsafety>
            ///   It is safe to call this function from any thread.
            /// </threadsafety>
            /// <since>
            ///   This function is available since SDL 3.2.0.
            /// </since>
            /// <seealso cref="Brutal.SdlApi.Sdl.PInvoke.GetGamepadSensorData"/>
            /// <seealso cref="Brutal.SdlApi.Sdl.PInvoke.GetGamepadSensorDataRate"/>
            /// <seealso cref="Brutal.SdlApi.Sdl.PInvoke.SetGamepadSensorEnabled"/>
            public static bool GamepadHasSensor(SdlGamepad gamepad, SdlSensorType type) =>
                PInvoke.GamepadHasSensor(gamepad, type) != 0;

            /// <summary>
            ///   Set whether data reporting for a gamepad sensor is enabled.
            /// </summary>
            /// <param name="gamepad">the gamepad to update.</param>
            /// <param name="type">the type of sensor to enable/disable.</param>
            /// <param name="enabled">whether data reporting should be enabled.</param>
            /// <returns>
            ///   true on success or false on failure; call SDL_GetError() for more
            ///   information.
            /// </returns>
            /// <threadsafety>
            ///   It is safe to call this function from any thread.
            /// </threadsafety>
            /// <since>
            ///   This function is available since SDL 3.2.0.
            /// </since>
            /// <seealso cref="Brutal.SdlApi.Sdl.PInvoke.GamepadHasSensor"/>
            /// <seealso cref="Brutal.SdlApi.Sdl.PInvoke.GamepadSensorEnabled"/>
            public static bool SetGamepadSensorEnabled(SdlGamepad gamepad, SdlSensorType type, bool enabled) =>
                PInvoke.SetGamepadSensorEnabled(gamepad, type, enabled ? (byte)1 : (byte)0) != 0;

            /// <summary>
            ///   Query whether sensor data reporting is enabled for a gamepad.
            /// </summary>
            /// <param name="gamepad">the gamepad to query.</param>
            /// <param name="type">the type of sensor to query.</param>
            /// <returns>true if the sensor is enabled, false otherwise.</returns>
            /// <threadsafety>
            ///   It is safe to call this function from any thread.
            /// </threadsafety>
            /// <since>
            ///   This function is available since SDL 3.2.0.
            /// </since>
            /// <seealso cref="Brutal.SdlApi.Sdl.PInvoke.SetGamepadSensorEnabled"/>
            public static bool GamepadSensorEnabled(SdlGamepad gamepad, SdlSensorType type) =>
                PInvoke.GamepadSensorEnabled(gamepad, type) != 0;

            /// <summary>
            ///   Get the data rate (number of events per second) of a gamepad sensor.
            /// </summary>
            /// <param name="gamepad">the gamepad to query.</param>
            /// <param name="type">the type of sensor to query.</param>
            /// <returns>the data rate, or 0.0f if the data rate is not available.</returns>
            /// <threadsafety>
            ///   It is safe to call this function from any thread.
            /// </threadsafety>
            /// <since>
            ///   This function is available since SDL 3.2.0.
            /// </since>
            public static float GetGamepadSensorDataRate(SdlGamepad gamepad, SdlSensorType type) =>
                PInvoke.GetGamepadSensorDataRate(gamepad, type);

            /// <summary>
            ///   Get the current state of a gamepad sensor.
            /// </summary>
            /// <param name="gamepad">the gamepad to query.</param>
            /// <param name="type">the type of sensor to query.</param>
            /// <param name="data">a pointer filled with the current sensor state.</param>
            /// <param name="num_values">the number of values to write to data.</param>
            /// <returns>
            ///   true on success or false on failure; call SDL_GetError() for more
            ///   information.
            /// </returns>
            /// <remarks>
            ///   <para>
            ///     The number of values and interpretation of the data is sensor dependent.
            ///     See the remarks in SDL_SensorType for details for each type of sensor.
            ///   </para>
            /// </remarks>
            /// <threadsafety>
            ///   It is safe to call this function from any thread.
            /// </threadsafety>
            /// <since>
            ///   This function is available since SDL 3.2.0.
            /// </since>
            public static bool GetGamepadSensorData(
                SdlGamepad gamepad,
                SdlSensorType type,
                float* data,
                int num_values
            ) => PInvoke.GetGamepadSensorData(gamepad, type, data, num_values) != 0;

            /// <summary>
            ///   Start a rumble effect on a gamepad.
            /// </summary>
            /// <param name="gamepad">the gamepad to vibrate.</param>
            /// <param name="low_frequency_rumble">
            ///   the intensity of the low frequency (left)
            ///   rumble motor, from 0 to 0xFFFF.
            /// </param>
            /// <param name="high_frequency_rumble">
            ///   the intensity of the high frequency (right)
            ///   rumble motor, from 0 to 0xFFFF.
            /// </param>
            /// <param name="duration_ms">the duration of the rumble effect, in milliseconds.</param>
            /// <returns>
            ///   true on success or false on failure; call SDL_GetError() for more
            ///   information.
            /// </returns>
            /// <remarks>
            ///   <para>
            ///     Each call to this function cancels any previous rumble effect, and calling
            ///     it with 0 intensity stops any rumbling.
            ///   </para>
            ///   <para>
            ///     This function requires you to process SDL events or call
            ///     SDL_UpdateJoysticks() to update rumble state.
            ///   </para>
            /// </remarks>
            /// <threadsafety>
            ///   It is safe to call this function from any thread.
            /// </threadsafety>
            /// <since>
            ///   This function is available since SDL 3.2.0.
            /// </since>
            public static bool RumbleGamepad(
                SdlGamepad gamepad,
                ushort low_frequency_rumble,
                ushort high_frequency_rumble,
                uint duration_ms
            ) => PInvoke.RumbleGamepad(gamepad, low_frequency_rumble, high_frequency_rumble, duration_ms) != 0;

            /// <summary>
            ///   Start a rumble effect in the gamepad's triggers.
            /// </summary>
            /// <param name="gamepad">the gamepad to vibrate.</param>
            /// <param name="left_rumble">
            ///   the intensity of the left trigger rumble motor, from 0
            ///   to 0xFFFF.
            /// </param>
            /// <param name="right_rumble">
            ///   the intensity of the right trigger rumble motor, from 0
            ///   to 0xFFFF.
            /// </param>
            /// <param name="duration_ms">the duration of the rumble effect, in milliseconds.</param>
            /// <returns>
            ///   true on success or false on failure; call SDL_GetError() for more
            ///   information.
            /// </returns>
            /// <remarks>
            ///   <para>
            ///     Each call to this function cancels any previous trigger rumble effect, and
            ///     calling it with 0 intensity stops any rumbling.
            ///   </para>
            ///   <para>
            ///     Note that this is rumbling of the <em>triggers</em> and not the gamepad as a
            ///     whole. This is currently only supported on Xbox One gamepads. If you want
            ///     the (more common) whole-gamepad rumble, use SDL_RumbleGamepad() instead.
            ///   </para>
            ///   <para>
            ///     This function requires you to process SDL events or call
            ///     SDL_UpdateJoysticks() to update rumble state.
            ///   </para>
            /// </remarks>
            /// <threadsafety>
            ///   It is safe to call this function from any thread.
            /// </threadsafety>
            /// <since>
            ///   This function is available since SDL 3.2.0.
            /// </since>
            /// <seealso cref="Brutal.SdlApi.Sdl.PInvoke.RumbleGamepad"/>
            public static bool RumbleGamepadTriggers(
                SdlGamepad gamepad,
                ushort left_rumble,
                ushort right_rumble,
                uint duration_ms
            ) => PInvoke.RumbleGamepadTriggers(gamepad, left_rumble, right_rumble, duration_ms) != 0;

            /// <summary>
            ///   Update a gamepad's LED color.
            /// </summary>
            /// <param name="gamepad">the gamepad to update.</param>
            /// <param name="red">the intensity of the red LED.</param>
            /// <param name="green">the intensity of the green LED.</param>
            /// <param name="blue">the intensity of the blue LED.</param>
            /// <returns>
            ///   true on success or false on failure; call SDL_GetError() for more
            ///   information.
            /// </returns>
            /// <remarks>
            ///   <para>
            ///     An example of a joystick LED is the light on the back of a PlayStation 4's
            ///     DualShock 4 controller.
            ///   </para>
            ///   <para>
            ///     For gamepads with a single color LED, the maximum of the RGB values will be
            ///     used as the LED brightness.
            ///   </para>
            /// </remarks>
            /// <threadsafety>
            ///   It is safe to call this function from any thread.
            /// </threadsafety>
            /// <since>
            ///   This function is available since SDL 3.2.0.
            /// </since>
            public static bool SetGamepadLED(SdlGamepad gamepad, byte red, byte green, byte blue) =>
                PInvoke.SetGamepadLED(gamepad, red, green, blue) != 0;

            /// <summary>
            ///   Send a gamepad specific effect packet.
            /// </summary>
            /// <param name="gamepad">the gamepad to affect.</param>
            /// <param name="data">the data to send to the gamepad.</param>
            /// <param name="size">the size of the data to send to the gamepad.</param>
            /// <returns>
            ///   true on success or false on failure; call SDL_GetError() for more
            ///   information.
            /// </returns>
            /// <threadsafety>
            ///   It is safe to call this function from any thread.
            /// </threadsafety>
            /// <since>
            ///   This function is available since SDL 3.2.0.
            /// </since>
            public static bool SendGamepadEffect(SdlGamepad gamepad, void* data, int size) =>
                PInvoke.SendGamepadEffect(gamepad, data, size) != 0;

