            /// <seealso cref="Brutal.SdlApi.Sdl.PInvoke.OpenGamepad"/>
            public static void CloseGamepad(SdlGamepad gamepad) => PInvoke.CloseGamepad(gamepad);

            /// <summary>
            ///   Return the sfSymbolsName for a given button on a gamepad on Apple
            ///   platforms.
