            /// </since>
            /// <seealso cref="Brutal.SdlApi.Sdl.PInvoke.GetGamepadAppleSFSymbolsNameForButton"/>
            public static string? GetGamepadAppleSFSymbolsNameForAxis(SdlGamepad gamepad, SdlGamepadAxis axis) =>
